\u0034\u0041\u003a\u0024\u0047\u0053\u006b\u004b\u0032\u0033\u0055\u005a\u0027\u004c\u0057\u007c\u0042\u0048\u0069\u007a\u007d\u0023\u0075\u0027\u0069\u006d\u007d\u0029\u0023\u0077\u005b\u0062\u0035\u005e\u003a\u006e\u0064\u0025\u002b\u0043\u0051\u0073\u002a\u0043\u004b\u0065\u003b\u0066\u0071\u0053\u002f\u006b\u0030\u006e\u003f\u0040\u0044\u006d\u0038\u0054\u005a\u006c\u0078\u0021\u004e\u0078\u0020\u0048\u0065\u0065\u0066\u005a\u0048\u002a\u0067\u0073\u0035\u004f\u0041\u004a\u0052\u0047\u002a\u0038\u002e\u0038\u004b\u0038\u0022\u0022\u0023\u0041\u0057\u005f\u0049\u0029\u004d\u0028\u0039\u0070\u0040\u0033\u005c\u0060\u006d\u003c\u0035\u0030\u005e\u003d\u0078\u0053\u0031\u0067\u0077\u0044\u004e\u0077\u0058\u0064\u0045\u0036\u002e\u0042\u0054\u0026\u0050\u0031\u0023\u0036\u0025\u0042\u004d\u0069\u0076\u0052\u006a\u002e\u0038\u0074\u0058\u0022\u0057\u0063\u004f\u005a\u0049\u0065\u003e\u0051\u0043\u0072\u0056\u004d\u004c\u0075\u0072\u0023\u002d\u0062\u0026\u0035\u005a\u0052\u005a\u0052\u003d\u007c\u004f\u0039\u0037\u0052\u0023\u0036\u0052\u0038\u002f\u004c\u004a\u0067\u0028\u0043\u005c\u003b\u0079\u0068\u003c\u0026\u0070\u004b\u0060\u002a\u002e\u0061\u0028\u0049\u007c\u0057\u0067\u002e\u004c\u004d\u0064\u0025\u0062\u006d\u005a\u004d\u0075\u003c\u0048\u0072\u007b\u0060\u004c\u0077\u0036\u005d\u0079\u0038\u006b\u0029\u0045\u0051\u0058\u0033\u002a\u0038\u0056\u006d\u0067\u0053\u0073\u0062\u003a\u0067\u003f\u002f\u0045\u007d\u0053\u002f\u0070\u0058\u0058\u0050\u006c\u0040\u005c\u0029\u0054\u0073\u0025\u0041\u0053\u0029\u0030\u0058\u0022\u003a\u0060\u0033\u0036\u0077\u0036\u0029\u005a\u003d\u0074\u0026\u003f\u003d\u0047\u002f\u006f\u0076\u0023\u007c\u0032\u0056\u0047\u002e\u0070\u0041\u005c\u0023\u006a\u0020\u0044\u0021\u002a\u004e\u0038\u006c\u0024\u005d\u0065\u002a\u0024\u006d\u007c\u0050\u005a\u003d\u0043\u0039\u0068\u0040\u0053\u0038\u0077\u0061\u004b\u006c\u0027\u0043\u0042\u0054\u006e\u0034\u0055\u0055\u004f\u0040\u0029\u0021\u0031\u0042\u0069\u0077\u005a\u007e\u006b\u007a\u0042\u0060\u003a\u0079\u0076\u002a\u007a\u003f\u0060\u007c\u0034\u0051\u0067\u0067\u0026\u0033\u0070\u002e\u002e\u0066\u0041\u0035\u0020\u003b\u004c\u0042\u003d\u0027\u006f\u0042\u0035\u0042\u0036\u0056\u007d\u0023\u0069\u004b\u0026\u0043\u0021\u002b\u0067\u007c\u0058\u007c\u006f\u007b\u007e\u0021\u007c\u0046\u0039\u006a\u004e\u0034\u0022\u004c\u0071\u0047\u0041\u007e\u0069\u0047\u0032\u0038\u0032\u003f\u0076\u0045\u0031\u0057\u0045\u0025\u0033\u004b\u002d\u005d\u0044\u0073\u005e\u002e\u0050\u006a\u0071\u0061\u0071\u002c\u0065\u0067\u004f\u0031\u002b\u0075\u002e\u007a\u0055\u0066\u006c\u005b\u007e\u0029\u005d\u0030\u003f\u0064\u003e\u002d\u003e\u0053\u0024\u0041\u007e\u0072\u007b\u0050\u006d\u0043\u0022\u0025\u004e\u0050\u002c\u0044\u007a\u0065\u003c\u0053\u004d\u0026\u003d\u002a\u0024\u0024\u0047\u0027\u0061\u0060\u0057\u0020\u003e\u002c\u003c\u0059\u0050\u002f\u005d\u005b\u0065\u005b\u0055\u0030\u0039\u0057\u0047\u004d\u007b\u0073\u006a\u004c\u0078\u0055\u0047\u005d\u0031\u003b\u0035\u007a\u003f\u006a\u0038\u0074\u0052\u0050\u002f\u0047\u0061\u006c\u0036\u0058\u0062\u0065\u0027\u0074\u0079\u0047\u0024\u0047\u0066\u003c\u0051\u005a\u0047\u003b\u0049\u0032\u007d\u006b\u004d\u002b\u0028\u0024\u002c\u003e\u0060\u0025\u0024\u002c\u004f\u0033\u0043\u0028\u0060\u004a\u0046\u0077\u0034\u0036\u006d\u0061\u004e\u0022\u0022\u003f\u005c\u003f\u006e\u0025\u0054\u0033\u0077\u0075\u0074\u0070\u0025\u0020\u0063\u0062\u0027\u0030\u0076\u003b\u004c\u0059\u006b\u0045\u0027\u002f\u0065\u0052\u0031\u005a\u002b\u0061\u002c\u0051\u0061\u002b\u0030\u0072\u0079\u005c\u005b\u0043\u0037\u003b\u007e\u004a\u0024\u0069\u006c\u0062\u0052\u003c\u0076\u002c\u006b\u0062\u0021\u007d\u006d\u005d\u0055\u0023\u007c\u0046\u006d\u0048\u0072\u0052\u0063\u007b\u0050\u004a\u0063\u0075\u005a\u006e\u0043\u003e\u0025\u0038\u0037\u007a\u0056\u004b\u003c\u004b\u0026\u0039\u002f\u0047\u002e\u0042\u002f\u003b\u005d\u0028\u0045\u0042\u0065\u003d\u0037\u0021\u0033\u007e\u0065\u0030\u006b\u0044\u003e\u0059\u0055\u0035\u005d\u003d\u007b\u0074\u0032\u0044\u0032\u005b\u0053\u0052\u007a\u0051\u003f\u0072\u003b\u005c\u0077\u0038\u0038\u0054\u006e\u0046\u0072\u0053\u0032\u004e\u0040\u0069\u0065\u0028\u002c\u002f\u0060\u0022\u007a\u0077\u0067\u0057\u0039\u0020\u0075\u004f\u0028\u0033\u0073\u004c\u0077\u0051\u0066\u0061\u005e\u005e\u0071\u0022\u0072\u002a\u0064\u0036\u002b\u0043\u0053\u0036\u0029\u0071\u0052\u0074\u0073\u002c\u0063\u007a\u004b\u0050\u004b\u0071\u002c\u0046\u0039\u0060\u004e\u0061\u0066\u0046\u0054\u0069\u0027\u0028\u0025\u0057\u0031\u0027\u0044\u0042\u002f\u0050\u002c\u007b\u0079\u006c\u0076\u0064\u0070\u0031\u007c\u0072\u0046\u0043\u0026\u004c\u0046\u004b\u0026\u005f\u003e\u0072\u004d\u007c\u006a\u0053\u0036\u0052\u003d\u0033\u0065\u0031\u0035\u0052\u004d\u003b\u005e\u005f\u004f\u0073\u007c\u0060\u0047\u002d\u004c\u0060\u0053\u0076\u004a\u007a\u0071\u0046\u0060\u003a\u004f\u0048\u003f\u004f\u004a\u0064\u0043\u0052\u0052\u0022\u0033\u004a\u007e\u0045\u0020\u007a\u0033\u0059\u0075\u0040\u004d\u007b\u006a\u007a\u0077\u0024\u0069\u0029\u006a\u0040\u0043\u0031\u0067\u0079\u007b\u0055\u0049\u0071\u0023\u0070\u004d\u0023\u0070\u0044\u007e\u0078\u0045\u0065\u0043\u0060\u0037\u0065\u0043\u004b\u003a\u0041\u002f\u003d\u002e\u0066\u0049\u007c\u002a\u007e\u005c\u005d\u003f\u0032\u0043\u0079\u0079\u0069\u004d\u006a\u006d\u0043\u0045\u0028\u0042\u0047\u0049\u0068\u005c\u0053\u0043\u005b\u0037\u0032\u0074\u0066\u0061\u003f\u007a\u0053\u003d\u0042\u006c\u0037\u007c\u0052\u0053\u0048\u007e\u0047\u005f\u0030\u0047\u007a\u002c\u005c\u005c\u004a\u0071\u006b\u005f\u005e\u004c\u0076\u003f\u0022\u0063\u0024\u0064\u0050\u004f\u003b\u0056\u007c\u0062\u004a\u006f\u0065\u0079\u0052\u0021\u0033\u0023\u0076\u0025\u0037\u0068\u003e\u0066\u0054\u006e\u005f\u002c\u006b\u0076\u004b\u003e\u0079\u0067\u0035\u004e\u0041\u0067\u0037\u0072\u0028\u004c\u0030\u0073\u0069\u004a\u005b\u003b\u003f\u004c\u002d\u0028\u006c\u0067\u003d\u003b\u0030\u0020\u0079\u0051\u0021\u002f\u0077\u006a\u0048\u0063\u007d\u0036\u003d\u0059\u0074\u0066\u004c\u002a\u0076\u005f\u007d\u006f\u0030\u006d\u0039\u002a\u002a\u003e\u003f\u0031\u0071\u0048\u0045\u0071\u0041\u0035\u0068\u0052\u0078\u005e\u007b\u006e\u0044\u007c\u0078\u0065\u0063\u003a\u0077\u005e\u0039\u0052\u0035\u0042\u0061\u0075\u007c\u0066\u0058\u0038\u0043\u0038\u0063\u004b\u005a\u0060\u0040\u0051\u0067\u003b\u0038\u0025\u0071\u0044\u003d\u0054\u0023\u0053\u0076\u0037\u0040\u007a\u0070\u003e\u0074\u0052\u006c\u0024\u006b\u0035\u003c\u0069\u0074\u007e\u0040\u0051\u004f\u0040\u006c\u002f\u0066\u0060\u0026\u0057\u007d\u006e\u004d\u0039\u0051\u0069\u0046\u003e\u006d\u006b\u0076\u0038\u006c\u0032\u0026\u0050\u0025\u0034\u004a\u0057\u0032\u0025\u0051\u005d\u0048\u003f\u0030\u0023\u0065\u002a\u0059\u002e\u003d\u007d\u006e\u004a\u006c\u005d\u0071\u0052\u003f\u0034\u0020\u0041\u0053\u0057\u004e\u005a\u0050\u003f\u005c\u004b\u0032\u004f\u0077\u003a\u0065\u003b\u0037\u0034\u0058\u004b\u0047\u0042\u0041\u002c\u0062\u0043\u002c\u0065\u0065\u004d\u0072\u004a\u006b\u0058\u0063\u005b\u0046\u0064\u002d\u006d\u0071\u0031\u0074\u007d\u0053\u0070\u0032\u0041\u002f\u0032\u0052\u0057\u0022\u0023\u0031\u0030\u0053\u003c\u007b\u003c\u006e\u0063\u0020\u0060\u0029\u003a\u0069\u0039\u002c\u0044\u0048\u0020\u0060\u0076\u0035\u0054\u0047\u0065\u0061\u0044\u0063\u0047\u0031\u0053\u0079\u0068\u002f\u004a\u0054\u0061\u002a\u004d\u002c\u007d\u003d\u003e\u0037\u0064\u0029\u002b\u0074\u007e\u006e\u003c\u006a\u006c\u0048\u0029\u0073\u0057\u005e\u0028\u0031\u0047\u006f\u002f\u0036\u0040\u007b\u0022\u005c\u0036\u002a\u0079\u0064\u004e\u002b\u005f\u0069\u006d\u0054\u0037\u002a\u004e\u006a\u0026\u004f\u0059\u0065\u0074\u0053\u003c\u006d\u006d\u0061\u007d\u005d\u002e\u0059\u0070\u0038\u005c\u0020\u0058\u002d\u0021\u0066\u003e\u0023\u0035\u007d\u0060\u0076\u002b\u007e\u0023\u0079\u005e\u0068\u004c\u0026\u006e\u0079\u0022\u0063\u007d\u0073\u0040\u0022\u0033\u0031\u007b\u0021\u006b\u0021\u004c\u0028\u007c\u0074\u005f\u0050\u002e\u004f\u0077\u0043\u003c\u0040\u0071\u0030\u0023\u0031\u0050\u0058\u006a\u0024\u005b\u0074\u007a\u0079\u0055\u0031\u0046\u007c\u005e\u0077\u0064\u0044\u0062\u0054\u004e\u0038\u0058\u004c\u005b\u004c\u006f\u0059\u0048\u005d\u0031\u0025\u0021\u003d\u004f\u002a\u007c\u0066\u0059\u0047\u0073\u006f\u0074\u0055\u0064\u0020\u0041\u0033\u0035\u0032\u003b\u0037\u0061\u004c\u0040\u005e\u0071\u0029\u0022\u0060\u0035\u005d\u0045\u007e\u006b\u0038\u0020\u0038\u0070\u005d\u0037\u005b\u005f\u0038\u0034\u0068\u0052\u0069\u0025\u0030\u0025\u006e\u006b\u004a\u0076\u0061\u0039\u005b\u0072\u0038\u0058\u007d\u0074\u005c\u0078\u0026\u005f\u0029\u0064\u0079\u0076\u007b\u002f\u002c\u003c\u0022\u002a\u007e\u003a\u005f\u005a\u006d\u002b\u005a\u002d\u0045\u0036\u006a\u0048\u0076\u003b\u0044\u005e\u003c\u002a\u0024\u002c\u006d\u0068\u003f\u007a\u0052\u0071\u004a\u0078\u0040\u007a\u0050\u0043\u006b\u0029\u0037\u0027\u0072\u0026\u0065\u0027\u006a\u0024\u0056\u0027\u0072\u0077\u004c\u004a\u0057\u0032\u0027\u0047\u002e\u0044\u0039\u0024\u003c\u003d\u007c\u0070\u002a\u0025\u006a\u0067\u0044\u0044\u003c\u003e\u0039\u002c\u0040\u004b\u003e\u0021\u0048\u007d\u0044\u0079\u006c\u004e\u0029\u0036\u004a\u0029\u006f\u0060\u0074\u0073\u0072\u002e\u0025\u0056\u002c\u004e\u006e\u0025\u005e\u005a\u0040\u0036\u002d\u0052\u006d\u004d\u004b\u0074\u0032\u0049\u0075\u002c\u0062\u0034\u0047\u0056\u0041\u0023\u0040\u0035\u0079\u007d\u0039\u007e\u0039\u0064\u0044\u0061\u0041\u0075\u006e\u007c\u0052\u0077\u0054\u0049\u002f\u006c\u006a\u0066\u004b\u0058\u0051\u0068\u0078\u0026\u007b\u0079\u0074\u0051\u0036\u0034\u0076\u0056\u002d\u005f\u0036\u0037\u0029\u0076\u0077\u005c\u0034\u0071\u005f\u0054\u002e\u003a\u006f\u0079\u0055\u0038\u004b\u006e\u0023\u0053\u003e\u0024\u0046\u005a\u0045\u0048\u004d\u007b\u003a\u005e\u0064\u0065\u0057\u0066\u003f\u0022\u0043\u004a\u0032\u004d\u0053\u007a\u002b\u006d\u0022\u004f\u0059\u004c\u0066\u006b\u003a\u0073\u0052\u0047\u0056\u0030\u003b\u002e\u007d\u0064\u005a\u0021\u0035\u006b\u0023\u0054\u0029\u0043\u004d\u006f\u006d\u002c\u006d\u0076\u006e\u0049\u006c\u0029\u0053\u0070\u0030\u0040\u0030\u007e\u0068\u0043\u0078\u0068\u0062\u0027\u0049\u004a\u0025\u002e\u007a\u0030\u0053\u003e\u0046\u0062\u003e\u0065\u002e\u0036\u002f\u0056\u004a\u003d\u0070\u004f\u0056\u0029\u003d\u004f\u0076\u002f\u0077\u0041\u0069\u0034\u0077\u0062\u0037\u0054\u006a\u0053\u006c\u0042\u0049\u005c\u004e\u006c\u0076\u0061\u0038\u006e\u003e\u0077\u003e\u007c\u004a\u0056\u0045\u003a\u0057\u002f\u006c\u0051\u0075\u0074\u0025\u0038\u004b\u0062\u003d\u0070\u0075\u0077\u006f\u007c\u0057\u0029\u005f\u0051\u0070\u0028\u0060\u0020\u007a\u0026\u005b\u0060\u006a\u003a\u0037\u0053\u0048\u0057\u003d\u0054\u0029\u0025\u007a\u0043\u003f\u002c\u003c\u006f\u0054\u006b\u003e\u0078\u006b\u0025\u0026\u0059\u0050\u007d\u002f\u005d\u002f\u005f\u002f\u0021\u0062\u0048\u0063\u0060\u005b\u0065\u007b\u006a\u003f\u0027\u0047\u003c\u006e\u006b\u007e\u0022\u0060\u005d\u002b\u0076\u0042\u0079\u003c\u006a\u0065\u0068\u002c\u002b\u0055\u0022\u0022\u002d\u0062\u0036\u0032\u0023\u002a\u0065\u006e\u006f\u003c\u006f\u002b\u006a\u0059\u0020\u0071\u0053\u0068\u0053\u006e\u005f\u005a\u0036\u0069\u0074\u0024\u0024\u005a\u004d\u007c\u0056\u0054\u0043\u0073\u0079\u002e\u002a\u0038\u0053\u0036\u0048\u003a\u0060\u0026\u005a\u0035\u005b\u002f\u002e\u0028\u006e\u0020\u007b\u0061\u0043\u0044\u0074\u0058\u006c\u0048\u003f\u007c\u0077\u0073\u0052\u0046\u0030\u0049\u005d\u0062\u0061\u0038\u0052\u0028\u0020\u0030\u005b\u0062\u0033\u004c\u0038\u0076\u0050\u003c\u003b\u0076\u0060\u006a\u0040\u0067\u007e\u0031\u0030\u007a\u0035\u0042\u004e\u0074\u0073\u007e\u0048\u0067\u0028\u0034\u003a\u002e\u002c\u0052\u0062\u002b\u004b\u0075\u0044\u007a\u003b\u0058\u0031\u0048\u0024\u007a\u006c\u003f\u006d\u006d\u007e\u006c\u0059\u003c\u004e\u0064\u0028\u0036\u006f\u0045\u0075\u0061\u0059\u007b\u0025\u007e\u0058\u004e\u0065\u0025\u0067\u0045\u0073\u003e\u004f\u005d\u0053\u004e\u0042\u0032\u0022\u002d\u006d\u0043\u002b\u006b\u0032\u0076\u0074\u007e\u0025\u004a\u003c\u0071\u003b\u0079